files.agent-pane/theme.css:
/* The Leo collection's agent pane: links and the caret in the theme's accent, so a chat reads
   in the same violet (or pink) as the sidebar, the terminal and every collection extension.
   Colors come from the theme file; this only points more of the pane at them. */
:root {
  --agent-link: var(--agent-accent);
}

textarea,
[contenteditable="true"] {
  caret-color: var(--agent-accent);
}

files.markdown/theme.css:
/* The Leo collection's Markdown pages: headings a little bolder, inline highlights tinted with
   the theme's accent. Colors come from the theme file. */
:root {
  --cmux-md-heading-weight: 650;
  --cmux-md-accent-background: color-mix(in srgb, var(--cmux-accent, currentColor) 14%, transparent);
}
